database_schema:
CREATE TABLE users (id UUID PRIMARY KEY, name VARCHAR(100), email VARCHAR(100) UNIQUE, password_hash VARCHAR(255));
CREATE TABLE sprints (id UUID PRIMARY KEY, name VARCHAR(100), start_date DATE, end_date DATE);
CREATE TABLE tasks (id UUID PRIMARY KEY, title VARCHAR(255), description TEXT, status VARCHAR(50), assigned_to UUID REFERENCES users(id), sprint_id UUID REFERENCES sprints(id));
